                + size_of::<Result<(), Diagnostic>>(),
            phase,
        )?;
        budget.reserve_vec(function, &mut self.nodes, 1, phase)?;
        budget.charge(function, 7, phase)?;
        self.nodes.push(IndexNode {
            byte: NIL,
            mask: 0,
            zero: index,
            one: NIL,
        });
