            function,
            2 * size_of::<(
                &mut StatusIndex,
                &IndexSearch,
                usize,
                &ResolvedFunction,
                &mut ReplayBudget,
                &str,
            )>() + 2 * size_of::<IndexNode>()
                + size_of::<Result<(), Diagnostic>>()
                + 2 * size_of::<usize>(),
            phase,
        )?;
        budget.reserve_vec(function, &mut self.nodes, 2, phase)?;
        budget.charge(function, 18, phase)?;
        let leaf = self.nodes.len();
        let branch = leaf + 1;
        self.nodes.push(IndexNode {
            byte: NIL,
            mask: 0,
            zero: index,
            one: NIL,
        });
